-- VAT return cages per taxable period, generated from "VAT Return_Upload 1.xlsx" (65 periods).
-- Run after migrations 0001-0006. Re-runnable: existing periods are updated, ledger figures are kept.
set search_path = vat_claims, public;
on conflict (company_id, return_month) do update set
  submitted_on = excluded.submitted_on,
  taxable_value = excluded.taxable_value,
  taxable_tax = excluded.taxable_tax,
  wholesale_retail = excluded.wholesale_retail,
  suspended_supplies = excluded.suspended_supplies,
  output_tax = excluded.output_tax,
  zero_rated = excluded.zero_rated,
  zero_rated_services = excluded.zero_rated_services,
  exempt = excluded.exempt,
  excluded_supplies = excluded.excluded_supplies,
  imports_value = excluded.imports_value,
  imports_deferred = excluded.imports_deferred,
  imports_upfront = excluded.imports_upfront,
  local_value = excluded.local_value,
  local_tax = excluded.local_tax,
  suspended_purchases_value = excluded.suspended_purchases_value,
  suspended_purchases_tax = excluded.suspended_purchases_tax,
  imports_no_vat = excluded.imports_no_vat,
  disallowed = excluded.disallowed,
  disallowed_suspended = excluded.disallowed_suspended,
  brought_forward = excluded.brought_forward,
  allowable_zero_rated = excluded.allowable_zero_rated,
  not_group_a = excluded.not_group_a,
  gross_refund = excluded.gross_refund,
  tax_payable = excluded.tax_payable,
  monthly_payments = excluded.monthly_payments,
  svat_credit = excluded.svat_credit,
  total_credits = excluded.total_credits,
  net_refund_payable = excluded.net_refund_payable,
  updated_at = now();
